using FluentAssertions;using FuelFlow.Features.Vouchers;using FuelFlow.Features.Vouchers.SharedModels;using FuelFlow.Persistence;using FuelFlow.SharedKernel.Domain;using Microsoft.EntityFrameworkCore;using Xunit;namespace FuelFlow.IntegrationTests;/// <summary>/// <c>is_test_data boolean</c> became <c>data_kind varchar NOT NULL CHECK (...)</c> on/// <c>fuel_offers</c> and <c>fuel_vouchers</c>. See <see cref="DataKinds"/> for the two production/// incidents that motivated it./// <para>/// The migration is hand-written because EF's scaffold was destructive. It emitted, in this order:/// <c>ADD COLUMN data_kind NOT NULL DEFAULT ''</c>, then <c>DROP COLUMN is_test_data</c>, then/// <c>UpdateData</c> setting <c>data_kind = 'real'</c> for the thirty rows in/// <c>SeedData.FuelOffers</c> and nothing else. Every row the seed does not know about - which is/// every voucher, and every package created at runtime rather than shipped — would have landed on/// <c>''</c> and been rejected by the very CHECK the same migration adds./// </para>/// <para>/// <b>The shape of these tests is the point.</b> They do not assert on the seeded catalogue, because/// the seeded catalogue is exactly the part the broken scaffold got right. Each one inserts a row/// that <c>SeedData</c> has never heard of, so the assertion fails if the copy step is ever dropped,/// reordered after the DROP, or narrowed to the seed./// </para>/// </summary>[Collection("Integration Tests")]public sealed class DataKindMigrationTests : IClassFixture<TestDatabaseFixture>{    private readonly TestDatabaseFixture _fixture;    public DataKindMigrationTests(TestDatabaseFixture fixture) => _fixture = fixture;    private ApplicationDbContext CreateContext()        => new(new DbContextOptionsBuilder<ApplicationDbContext>()            .UseNpgsql(_fixture.ConnectionString)            .Options, TestQrCipher.Instance);    [Theory]    [InlineData("fuel_vouchers")]    [InlineData("fuel_offers")]    public async Task TheBooleanIsGone_ReplacedByANamedColumn(string table)    {        await using var context = CreateContext();        var columns = await context.Database.SqlQueryRaw<string>(            $"""             SELECT column_name AS "Value"             FROM information_schema.columns             WHERE table_name = '{table}' AND column_name IN ('data_kind', 'is_test_data')             """).ToListAsync();        columns.Should().BeEquivalentTo(["data_kind"],            "the named value replaced the boolean rather than sitting beside it");    }    [Theory]    [InlineData("fuel_vouchers")]    [InlineData("fuel_offers")]    public async Task TheColumnIsNotNull_AndPinnedToTheKnownSet(string table)    {        await using var context = CreateContext();        // SqlQueryRaw, not ExecuteSql*: ExecuteSql returns rows-affected (-1 for a SELECT), which        // compares equal to nothing and would have passed against any row count.        var nulls = await context.Database.SqlQueryRaw<int>(            $"SELECT count(*) FROM {table} WHERE data_kind IS NULL").ToListAsync();        nulls.Should().ContainSingle().Which.Should().Be(0);        // NOT NULL + CHECK is the whole point of the rename, so assert the constraint exists by        // name rather than trusting the migration ran - an absent CHECK is a silent regression.        var constraints = await context.Database.SqlQueryRaw<string>(            $"""             SELECT con.conname AS "Value"             FROM pg_constraint con             JOIN pg_class rel ON rel.oid = con.conrelid             WHERE rel.relname = '{table}'               AND con.conname = 'ck_{table}_data_kind'             """).ToListAsync();        constraints.Should().ContainSingle(            "a name is only worth having if the database pins the set");    }    [Fact]    public async Task ARowTheSeedDoesNotKnow_StillGetsAKind()    {        // The regression pin. Under the scaffolded ordering this insert would have failed on the        // CHECK with data_kind = '', and the failure would have appeared only on a database that        // actually holds stock.        var offer = NewOffer($"dk-offer-{Guid.NewGuid():N}");        var voucher = NewVoucher();        await using (var context = CreateContext())        {            context.FuelOffers.Add(offer);            context.FuelVouchers.Add(voucher);            await context.SaveChangesAsync();        }        await using var verify = CreateContext();        var storedOffer = await verify.FuelOffers.AsNoTracking().SingleAsync(o => o.Id == offer.Id);        var storedVoucher = await verify.FuelVouchers.AsNoTracking().SingleAsync(v => v.Id == voucher.Id);        storedOffer.DataKind.Should().Be(DataKinds.Real, "real unless somebody says otherwise");        storedVoucher.DataKind.Should().Be(DataKinds.Real);    }    [Fact]    public async Task TheQaFlag_RoundTrips_ThroughTheColumn()    {        var offer = NewOffer($"dk-qa-offer-{Guid.NewGuid():N}", isTestData: true);        var voucher = NewVoucher(isTestData: true);        await using (var context = CreateContext())        {            context.FuelOffers.Add(offer);            context.FuelVouchers.Add(voucher);            await context.SaveChangesAsync();        }        await using var verify = CreateContext();        var storedOffer = await verify.FuelOffers.AsNoTracking().SingleAsync(o => o.Id == offer.Id);        var storedVoucher = await verify.FuelVouchers.AsNoTracking().SingleAsync(v => v.Id == voucher.Id);        storedOffer.DataKind.Should().Be(DataKinds.Qa);        storedVoucher.DataKind.Should().Be(DataKinds.Qa);        // And the shim still reads correctly off a freshly materialised row, because that is how the        // admin DTOs are filled.        storedOffer.IsTestData.Should().BeTrue();        storedVoucher.IsTestData.Should().BeTrue();        // What a cleanup and the admin list filter on. Both arms compare the mapped column: the        // IsTestData shim is [NotMapped] and cannot be translated, so the boolean form of this        // predicate throws "could not be translated" at run time rather than failing to compile.        (await verify.FuelVouchers.CountAsync(v => v.DataKind == DataKinds.Qa && v.Id == voucher.Id))            .Should().Be(1);        (await verify.FuelVouchers.CountAsync(v => v.DataKind == DataKinds.Real && v.Id == voucher.Id))            .Should().Be(0);    }    [Fact]    public async Task AnUnknownKind_IsRefusedByTheDatabase()    {        await using var context = CreateContext();        context.FuelVouchers.Add(NewVoucher(dataKind: "sandbox"));        var act = async () => await context.SaveChangesAsync();        await act.Should().ThrowAsync<DbUpdateException>(            "the CHECK is what stops the next unrehearsed rehearsal row from being sellable");    }    [Fact]    public void TheShim_MapsBothWays_InMemory()    {        // The C# surface stays a bool, so every caller that asks "is this the QA pool?" reads the        // same way - only the storage underneath changed.        var package = new FuelPackage();        var voucher = new FuelVoucher();        package.DataKind.Should().Be(DataKinds.Real);        voucher.DataKind.Should().Be(DataKinds.Real);        voucher.IsTestData = true;        voucher.DataKind.Should().Be(DataKinds.Qa, "assigning the shim is how the write paths state intent");        package.IsTestData = true;        package.DataKind.Should().Be(DataKinds.Qa);        voucher.IsTestData = false;        voucher.DataKind.Should().Be(DataKinds.Real);    }    [Theory]    [InlineData("real", true)]    [InlineData("qa", true)]    [InlineData("sandbox", false)]    [InlineData("qa", false)]    [InlineData("", false)]    [InlineData(null, false)]    public void IsKnown_AcceptsOnlyTheTwoPools(string? kind, bool expected)    {        // The set is case-sensitive on purpose: the column is written by two constants, and a        // case-insensitive check would imply a looser contract than the database enforces.        DataKinds.IsKnown(kind).Should().Be(expected);    }    /// <summary>    /// The pool is a property of the OFFER - it is what the storefront filters on and what    /// <c>EnforceDataKind</c> backfilled. So this seeds an offer, where the old version seeded a    /// package row, and every assertion below moved with it.    /// </summary>    private static FuelOffer NewOffer(string id, bool isTestData = false)        => new()        {            Id = id,            BrandId = "okko-0001",            FuelTypeId = "okko-95",            SupplierPricePerLiter = 50m,            IsTestData = isTestData,            CreatedAtUtc = DateTime.UtcNow,            UpdatedAtUtc = DateTime.UtcNow        };    private static FuelVoucher NewVoucher(bool isTestData = false, string? dataKind = null)    {        var expiry = DateOnly.FromDateTime(DateTime.UtcNow.AddMonths(3));        var voucher = new FuelVoucher        {            Id = Guid.NewGuid(),            Brand = "okko",            FuelTypeId = "okko-95",            Liters = 10m,            SupplierExpirationDate = expiry,            CustomerExpirationDate = expiry,            VoucherNumber = $"dk-{Guid.NewGuid():N}",            QrPayload = $"dk-qr-{Guid.NewGuid():N}",            Status = VoucherStatus.Available,            IsTestData = isTestData,            CreatedAtUtc = DateTime.UtcNow,            UpdatedAtUtc = DateTime.UtcNow        };        if (dataKind is not null)            voucher.DataKind = dataKind;        return voucher;    }}